typedef struct { const char *key; shape_t *(*make)(const void *cfg); } entry_t;
static entry_t registry[16]; static size_t registry_len;

void register_shape(const char *key, shape_t *(*make)(const void *cfg))
{ registry[registry_len++] = (entry_t){ key, make }; }   /* add duplicate check */

shape_t *create_shape(const char *key, const void *cfg) {
    for (size_t i = 0; i < registry_len; ++i)
        if (strcmp(registry[i].key, key) == 0) return registry[i].make(cfg);
    return NULL;                                          /* unknown key */
}
